function expirationDateField(value){return `<div class="expiration-field"><label for="expiryInput">Expiration date <span class="optional-label">(optional)</span></label><div class="date-input-wrap"><input id="expiryInput" name="expiry" type="text" value="${esc(formatUSDate(value))}" placeholder="MM/DD/YYYY" maxlength="10" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}" autocomplete="off"><button type="button" id="calendarToggle" aria-label="Choose expiration date" aria-expanded="false" aria-controls="expiryCalendar"><svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v5m10-5v5M3 11h18m-13 4h2m4 0h2m-8 3h2"/></svg></button></div><div id="expiryCalendar" class="calendar-panel" role="group" aria-label="Expiration date calendar" hidden><div class="calendar-navigation"><button type="button" id="calendarPrevious" class="calendar-nav" aria-label="Previous month">‹</button><select id="calendarMonth" aria-label="Calendar month"></select><select id="calendarYear" aria-label="Calendar year"></select><button type="button" id="calendarNext" class="calendar-nav" aria-label="Next month">›</button></div><div class="calendar-weekdays" aria-hidden="true">${['Su','Mo','Tu','We','Th','Fr','Sa'].map(day=>`<span>${day}</span>`).join('')}</div><div id="calendarDays" class="calendar-days" role="group" aria-label="Choose a day"></div><div class="calendar-footer"><button type="button" id="calendarToday">Today</button><button type="button" id="calendarClear">Clear</button><button type="button" id="calendarDone">Done</button></div><span class="calendar-announcement" id="calendarAnnouncement" aria-live="polite"></span></div><p class="date-help">Choose from the calendar or enter MM/DD/YYYY.</p></div>`;}
function calendarISO(year,month,day){return String(year).padStart(4,'0')+'-'+String(month+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');}
function calendarCells(year,month){return [...Array(new Date(year,month,1).getDay()).fill(null),...Array.from({length:new Date(year,month+1,0).getDate()},(_,index)=>({day:index+1,iso:calendarISO(year,month,index+1)}))];}
function setupExpirationCalendar(){const input=$('#expiryInput'),toggle=$('#calendarToggle'),panel=$('#expiryCalendar'),days=$('#calendarDays'),monthSelect=$('#calendarMonth'),yearSelect=$('#calendarYear');const monthNames=['January','February','March','April','May','June','July','August','September','October','November','December'];let year,month,selected='';const now=()=>new Date();const hide=(focus=true)=>{panel.hidden=true;toggle.setAttribute('aria-expanded','false');if(focus)toggle.focus();};
 function draw(focusISO){monthSelect.innerHTML=monthNames.map((name,index)=>`<option value="${index}" ${index===month?'selected':''}>${name}</option>`).join('');const years=[...new Set([...Array.from({length:201},(_,index)=>1900+index),year])].sort((a,b)=>a-b);yearSelect.innerHTML=years.map(value=>`<option value="${value}" ${value===year?'selected':''}>${value}</option>`).join('');const today=now(),todayISO=calendarISO(today.getFullYear(),today.getMonth(),today.getDate());days.innerHTML=calendarCells(year,month).map(cell=>cell?`<button type="button" class="calendar-day ${cell.iso===todayISO?'is-today':''} ${cell.iso===selected?'is-selected':''}" data-date="${cell.iso}" aria-label="${monthNames[month]} ${cell.day}, ${year}" aria-pressed="${cell.iso===selected}" ${cell.iso===todayISO?'aria-current="date"':''}>${cell.day}</button>`:'<span aria-hidden="true"></span>').join('');$('#calendarAnnouncement').textContent=monthNames[month]+' '+year;if(focusISO)days.querySelector(`[data-date="${focusISO}"]`)?.focus();}
 function choose(iso){input.value=formatUSDate(iso);input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));selected=iso;hide(false);input.focus();}
 function move(amount){const target=new Date(year,month+amount,1);year=target.getFullYear();month=target.getMonth();draw();}
 toggle.onclick=()=>{if(!panel.hidden){hide();return}try{selected=parseUSDate(input.value)}catch{selected=''}const parts=selected?selected.split('-').map(Number):null,today=now();year=parts?parts[0]:today.getFullYear();month=parts?parts[1]-1:today.getMonth();panel.hidden=false;toggle.setAttribute('aria-expanded','true');draw();};
 $('#calendarPrevious').onclick=()=>move(-1);$('#calendarNext').onclick=()=>move(1);monthSelect.onchange=()=>{month=Number(monthSelect.value);draw();};yearSelect.onchange=()=>{year=Number(yearSelect.value);draw();};
 days.onclick=e=>{const button=e.target.closest('button[data-date]');if(button)choose(button.dataset.date);};$('#calendarToday').onclick=()=>{const today=now();choose(calendarISO(today.getFullYear(),today.getMonth(),today.getDate()));};$('#calendarClear').onclick=()=>choose('');$('#calendarDone').onclick=()=>hide();
 panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();hide();return}const button=e.target.closest('button[data-date]');if(!button)return;const offsets={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7};if(!(e.key in offsets))return;e.preventDefault();const [y,m,d]=button.dataset.date.split('-').map(Number),target=new Date(y,m-1,d+offsets[e.key]);year=target.getFullYear();month=target.getMonth();draw(calendarISO(year,month,target.getDate()));});
}
